'use strict';
let KEY='pvz-control-v1';
try{const active=localStorage.getItem('pvz-control-active-key');if(/^pvz-control-tg-[1-9][0-9]*$/.test(active||''))KEY=active}catch{}
let storageFault=false, persistedSnapshot=null;
function writeLocal(value,{recover=false}={}){
 if(storageFault&&!recover)throw Error('Хранилище повреждено или недоступно. Сохраните исходные данные перед восстановлением.');
 if(localStorage.getItem(KEY)!==persistedSnapshot)throw Error('Данные изменились в другой вкладке. Обновите страницу.');
 if(storageFault&&recover)localStorage.setItem(KEY+'-damaged',persistedSnapshot||'');
 localStorage.setItem(KEY,value);persistedSnapshot=value;storageFault=false;
 window.dispatchEvent(new Event('pvz-saved'));
}

const REV='pvz-control-revision';
const roundMoney=n=>Math.round((n+Number.EPSILON)*100)/100;
const safeNumber=v=>typeof v==='number'&&Number.isFinite(v);
const monthPrefix=()=>`${year}-${String(month+1).padStart(2,'0')}`;
const empty=()=>({points:[],people:[],shifts:[],incidents:[],payments:[],notes:[],reviews:[],repayments:[],installments:[],settings:{mode:'standard'},history:[]});
let db;try{persistedSnapshot=localStorage.getItem(KEY);db=JSON.parse(persistedSnapshot)||empty()}catch{db=empty();storageFault=true}
if(!db||typeof db!=='object'||Array.isArray(db)){storageFault=true;db=empty()}
if(!Array.isArray(db.reviews))db.reviews=[]
if(!Array.isArray(db.repayments))db.repayments=[]
if(!Array.isArray(db.installments))db.installments=[]
if(!persistedSnapshot&&!storageFault){try{writeLocal(JSON.stringify(db))}catch(e){storageFault=true;console.warn(e)}}
let bulkSelection=false,selectedDates=new Set(),networkMarket='all',settingsQuery='',tab='calendar',pointId='',redo=[],month=new Date().getMonth(),year=new Date().getFullYear(),selectedDay=null,undo=[];
const id=()=>crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random());
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{writeLocal(JSON.stringify(db));render();return true}catch(e){alert('Не удалось сохранить данные: '+e.message+'\nОсвободите место и сохраните резервную копию.');return false}};
// Compare the persisted snapshot taken BEFORE mutation, not the migrated in-memory
// representation. Old versions did not have reviews/repayments/installments arrays.
const commit=(fn)=>{
 const before=JSON.stringify(db);
 let storedBefore;
 try{storedBefore=localStorage.getItem(KEY)}catch(e){sheetErrorSafe('Не удалось прочитать сохранённые данные: '+e.message);return false}
 try{
  fn();validate(db);
  if(localStorage.getItem(KEY)!==storedBefore)throw Error('Данные изменились в другой вкладке. Обновите страницу перед сохранением.');
  writeLocal(JSON.stringify(db));
  undo.push(before);if(undo.length>40)undo.shift();redo=[];
  render();return true;
 }catch(e){
  db=JSON.parse(before);
  sheetErrorSafe('Изменение не сохранено: '+e.message);
  return false;
 }
};
function sheetErrorSafe(message){
 const el=document.getElementById('sheet-error');
 if(el)el.textContent=message;
 else alert(message);
 console.error('[PVZ CONTROL] '+message);
}

const dateValid=(v)=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;
const amountValid=(v,allowZero=false)=>Number.isFinite(v)&&(allowZero?v>=0:v>0)&&v<=1e10;
function validate(x){if(!x||typeof x!=='object')throw Error('Неверная база');for(const k of ['points','people','shifts','incidents','payments','notes','history'])if(!Array.isArray(x[k]))throw Error('Отсутствует массив '+k);if(!x.settings||!['simple','standard','advanced'].includes(x.settings.mode))throw Error('Некорректный режим');const unique=(arr,label)=>{const ids=new Set();for(const item of arr){if(!item||typeof item.id!=='string'||!/^[a-zA-Z0-9_.:-]{1,100}$/.test(item.id)||ids.has(item.id))throw Error('Неверный ID: '+label);ids.add(item.id)}return ids};const pts=unique(x.points,'ПВЗ'),people=unique(x.people,'персонал');for(const q of x.points)if(!['wb','ozon','ym'].includes(q.market)||typeof q.name!=='string')throw Error('Некорректный ПВЗ');for(const q of x.people)if(!['manager','employee'].includes(q.role)||typeof q.name!=='string'||!amountValid(q.rate,true)||(q.hourlyRate!==undefined&&!amountValid(q.hourlyRate,true)))throw Error('Некорректный сотрудник');for(const k of ['shifts','incidents','payments','notes']){unique(x[k],k);for(const q of x[k])if(!pts.has(q.point)|| (q.person&&!people.has(q.person))||!dateValid(q.date))throw Error('Повреждённые связи или дата: '+k)}if(x.reviews!==undefined){unique(x.reviews,'оценки');for(const r of x.reviews)if(!people.has(r.person)||!pts.has(r.point)||!dateValid(r.date)||!Number.isInteger(r.negative)||r.negative<0||r.negative>100000||!Number.isInteger(r.rating)||r.rating<1||r.rating>5)throw Error('Некорректная оценка')}if(x.repayments!==undefined){unique(x.repayments,'погашения');for(const r of x.repayments){const incident=x.incidents.find(q=>q.id===r.incident);if(!incident||!pts.has(r.point)||!people.has(r.person)||incident.point!==r.point||incident.person!==r.person||!dateValid(r.date)||!amountValid(r.amount)||typeof r.note!=='string'||r.note.length>500)throw Error('Некорректная запись погашения')}for(const q of x.incidents){const sum=roundMoney(x.repayments.filter(r=>r.incident===q.id).reduce((a,r)=>a+r.amount,0));if(sum>q.amount+0.001)throw Error('Погашение превышает сумму происшествия')}}if(x.installments!==undefined){unique(x.installments,'рассрочки');for(const plan of x.installments){const q=x.incidents.find(z=>z.id===plan.incident);if(!q||q.point!==plan.point||q.person!==plan.person||!['active','paused','closed'].includes(plan.status)||!Array.isArray(plan.schedule)||!plan.schedule.length||!['informational','voluntary'].includes(plan.basis))throw Error('Повреждён график рассрочки');let total=0;for(const row of plan.schedule){if(!dateValid(row.date)||!amountValid(row.amount))throw Error('Некорректный платёж рассрочки');total+=row.amount}if(Math.abs(roundMoney(total)-plan.total)>0.01||plan.total>q.amount+0.001||!amountValid(plan.total))throw Error('Сумма графика рассрочки неверна')}}const seenShifts=new Set();for(const q of x.shifts){if(!people.has(q.person))throw Error('Смена без сотрудника');if(q.hours!==undefined&&(!safeNumber(q.hours)||q.hours<0||q.hours>24))throw Error('Некорректные часы смены');if(q.actual!==undefined&&typeof q.actual!=='boolean')throw Error('Некорректная отметка факта');for(const value of [q.rateSnapshot,q.hourlyRateSnapshot])if(value!==undefined&&!amountValid(value,true))throw Error('Некорректная сохранённая ставка');const key=q.point+'|'+q.person+'|'+q.date;if(seenShifts.has(key))throw Error('Дублирующаяся смена');seenShifts.add(key)}for(const q of x.payments)if(!people.has(q.person)||!safeNumber(q.amount)||!amountValid(q.amount))throw Error('Некорректная выплата');for(const q of x.incidents)if(!['штраф','претензия','брак','потеряшка','подмена','приёмка +','приёмка -','зависшие'].includes(q.type)||!['новое','рассматривается','оспаривается','подтверждено','отменено'].includes(q.status)||!people.has(q.person)||!safeNumber(q.amount)||!safeNumber(q.price)||!safeNumber(q.percent)||!amountValid(q.amount,true)||!amountValid(q.price,true)||q.percent<0||q.percent>200)throw Error('Некорректная сумма происшествия');return true}
function conflicting(personId,date,point,ignore=[]){return db.shifts.filter(s=>s.person===personId&&s.date===date&&s.point!==point&&!ignore.includes(s.id))}
function ensureNoConflicts(changes){const own=new Map();for(const s of changes){const k=s.person+'|'+s.date;if(person(s.person)?.role!=='manager'&&own.has(k)&&own.get(k)!==s.point){alert('Операция отменена: один сотрудник назначен на разные ПВЗ в одном пакете.');return false}own.set(k,s.point)}const conflicts=changes.filter(s=>person(s.person)?.role!=='manager'&&conflicting(s.person,s.date,s.point).length);if(conflicts.length){alert('Операция отменена: '+conflicts.length+' пересечений смен на разных ПВЗ. Измените график или назначьте другого сотрудника.');return false}return true}

const snapshot=()=>{undo.push(JSON.stringify(db));if(undo.length>20)undo.shift()};
const activePoint=()=>db.points.find(p=>p.id===pointId)||db.points[0];
const person=n=>db.people.find(p=>p.id===n);
const dateStr=d=>`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
const shiftAt=(p,d,role)=>db.shifts.filter(s=>s.point===p&&s.date===d&&(!role||person(s.person)?.role===role));
const patternDays=['2/2','3/2','2/3','1/1','2/1','1/2','5/2','2/5','7/0','5/2 (будни)'];
const colors=['#B99CDA','#8DC9C3','#E5AD86','#A6C8E7','#D5B77A','#C5ACD5'];
const tabs=[['calendar','Календарь'],['people','Сотрудники'],['network','Вся сеть'],['finance','Финансы'],['settings','Настройки']];
const MARKET_INFO={wb:{name:'Wildberries',short:'WB'},ozon:{name:'Ozon',short:'Ozon'},ym:{name:'Яндекс Маркет',short:'Я.Маркет'}};
// Minimalist marketplace-specific outline icon, used ONLY in the panel heading.
// Text is vector SVG, not an emoji or external image; currentColor follows the marketplace palette.
function marketStoreIcon(market){
 const word={wb:'WB',ozon:'OZON',ym:'М'}[market]||'ПВЗ';
 const size=market==='ozon'?'6.1':market==='wb'?'9.5':'13';
 return `<svg class="market-store-icon" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M8 18 12 7h24l4 11v23H8V18Z" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/><path d="M8 18h32M17 7h14" stroke="currentColor" stroke-width="2.8" stroke-linecap="round"/><text x="24" y="32" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-size="${size}" font-weight="800" fill="currentColor">${word}</text></svg>`;
}
function setMarketplace(market){const found=db.points.find(p=>p.market===market);if(!found)return;pointId=found.id;bulkSelection=false;selectedDates.clear();render()}
function setPoint(pid){if(!db.points.some(p=>p.id===pid))return;pointId=pid;bulkSelection=false;selectedDates.clear();render()}
function dashboard(p){
 if(!db.points.length)return `<section class="market-dashboard empty-dashboard"><h3>Мои пункты выдачи</h3><p>Добавьте первый ПВЗ, чтобы увидеть его календарь и показатели.</p><button class="primary" onclick="openSheet('point')">${ico('plus')} Добавить ПВЗ</button></section>`;
 const markets=['wb','ozon','ym'].filter(m=>db.points.some(p=>p.market===m));
 const choices=markets.map(m=>`<button type="button" class="market-choice ${p.market===m?'selected':''}" data-market="${m}" aria-pressed="${p.market===m}" onclick="setMarketplace('${m}')"><span>${MARKET_INFO[m].short}</span>${p.market===m?'<span class="market-tick" aria-hidden="true">✓</span>':''}</button>`).join('');
 const monthStart=monthPrefix();
 const shifts=db.shifts.filter(s=>s.point===p.id&&s.date.startsWith(monthStart));
 const staffIds=new Set([...shifts.map(s=>s.person),...db.people.filter(w=>!w.archived&&w.points?.includes(p.id)).map(w=>w.id)]);
 const staff=staffIds.size;
 const incidents=db.incidents.filter(x=>x.point===p.id&&x.status!=='отменено'&&x.status!=='подтверждено');
 const pending=db.installments.filter(x=>x.point===p.id&&x.status==='active').length;
 const market=MARKET_INFO[p.market];
 const options=db.points.filter(x=>x.market===p.market).map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('');
 const stat=(icon,value,label)=>`<div class="dashboard-stat">${ico(icon)}<strong>${value}</strong><span>${label}</span></div>`;
 return `<section class="market-dashboard" aria-label="Обзор пункта выдачи"><div class="market-hint">Выберите маркетплейс</div><div class="market-choices">${choices}</div><div class="market-panel" data-market="${p.market}"><div class="market-panel-heading"><div><span class="market-kicker">Панель управления</span><h3>${market.name}</h3></div>${marketStoreIcon(p.market)}</div><div class="dashboard-point"><label for="dashboard-point-select">Пункт выдачи</label><select id="dashboard-point-select" onchange="setPoint(this.value)">${options}</select></div><div class="dashboard-stats">${stat('calendar-days',shifts.length,'Смен в месяце')}${stat('users',staff,'Сотрудников')}${stat('alert',incidents.length,'Открытых проблем')}${stat('wallet',pending,'Активных рассрочек')}</div></div></section>`;
}
// Unclosed days are past scheduled shifts that have not been marked as worked.
// Date comparison uses the device's local calendar day (not UTC), so today's
// shift is never flagged prematurely.
function unclosedShifts(point){
 const now=new Date();
 const today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
 return db.shifts.filter(s=>s.date<today&&!s.actual&&(!point||s.point===point)).sort((a,b)=>a.date.localeCompare(b.date));
}
function openUnclosedShift(point,date){
 if(!db.points.some(p=>p.id===point))return;
 pointId=point;tab='calendar';bulkSelection=false;selectedDates.clear();
 year=Number(date.slice(0,4));month=Number(date.slice(5,7))-1;
 selectedDay=date;render();openSheet('day');
}
function unclosedNotice(point){
 const items=unclosedShifts(point);
 if(!items.length)return '';
 const days=new Set(items.map(s=>s.date)).size;
 const shown=items.slice(0,8);
 const list=shown.map(s=>{
  const w=person(s.person),p=db.points.find(p=>p.id===s.point);
  return `<button type="button" class="unclosed-item" onclick="openUnclosedShift('${esc(s.point)}','${esc(s.date)}')"><span class="unclosed-date">${esc(s.date.split('-').reverse().join('.'))}</span><span class="unclosed-person">${esc(w?.name||'Сотрудник не найден')}${point?'':`<small>${esc(p?.name||'ПВЗ')}</small>`}</span>${ico('chevron-right')}</button>`;
 }).join('');
 return `<section class="unclosed-notice" aria-label="Незакрытые смены"><button type="button" class="unclosed-heading notice-toggle" aria-expanded="false" onclick="toggleNotice(this)">${ico('alert')}<div><strong>Есть незакрытые смены</strong><p>Прошедших дат: ${days} · смен без отметки «Отработана»: ${items.length}</p></div>${ico('chevron-right')}</button><div class="notice-expanded" hidden><div class="unclosed-list">${list}</div>${items.length>shown.length?`<p class="unclosed-more">Показаны первые ${shown.length} из ${items.length}. Закрывайте смены через календарь.</p>`:''}<p class="unclosed-help">Нажмите на дату, чтобы проверить смену и отметить фактическую работу. Записи не закрываются автоматически.</p></div></section>`;
}
// Warn when no employee is scheduled for a future day. Use local calendar dates
// to avoid UTC timezone offsets and daylight-saving surprises.
function upcomingUnstaffedDays(point){
 const n=Number(db.settings?.vacantShiftAlertDays ?? 7);
 const range=Number.isInteger(n)&&n>=0&&n<=90?n:7;
 if(!range)return [];
 const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),now.getDate());
 const points=db.points.filter(p=>!point||p.id===point);
 const result=[];
 for(const p of points){
  for(let offset=0;offset<range;offset++){
   const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+offset);
   const day=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
   const assigned=db.shifts.some(s=>s.point===p.id&&s.date===day&&person(s.person)?.role==='employee'&&!person(s.person)?.archived);
   if(!assigned)result.push({point:p.id,date:day,name:p.name});
  }
 }
 return result.sort((a,b)=>a.date.localeCompare(b.date)||a.name.localeCompare(b.name,'ru'));
}
function openUnstaffedDay(pid,date){
 if(!db.points.some(p=>p.id===pid))return;
 pointId=pid;tab='calendar';bulkSelection=false;selectedDates.clear();
 year=Number(date.slice(0,4));month=Number(date.slice(5,7))-1;
 selectedDay=date;render();openSheet('day');
}
function unstaffedNotice(point){
 const days=upcomingUnstaffedDays(point);
 if(!days.length)return '';
 const range=Number(db.settings?.vacantShiftAlertDays ?? 7);
 const shown=days.slice(0,8);
 return `<section class="unclosed-notice vacant-notice" aria-label="Дни без назначенных сотрудников"><button type="button" class="unclosed-heading notice-toggle" aria-expanded="false" onclick="toggleNotice(this)">${ico('alert')}<div><strong>Не на все дни назначены сотрудники</strong><p>Ближайшие ${range} дн. (включая сегодня) · свободных дат: ${days.length}</p></div>${ico('chevron-right')}</button><div class="notice-expanded" hidden><div class="unclosed-list">${shown.map(d=>`<button type="button" class="unclosed-item" onclick="openUnstaffedDay('${esc(d.point)}','${esc(d.date)}')"><span class="unclosed-date">${esc(d.date.split('-').reverse().join('.'))}</span><span class="unclosed-person">Нет назначенного сотрудника${point?'':`<small>${esc(d.name)}</small>`}</span>${ico('chevron-right')}</button>`).join('')}</div>${days.length>shown.length?`<p class="unclosed-more">Показаны первые ${shown.length} из ${days.length} дат.</p>`:''}<p class="unclosed-help">Нажмите на дату, чтобы назначить сотрудника. Период предупреждений меняется в настройках.</p></div></section>`;
}
function toggleNotice(button){
 const section=button.closest('.unclosed-notice');
 if(!section)return;
 const content=section.querySelector('.notice-expanded');
 if(!content)return;
 const expanding=button.getAttribute('aria-expanded')!=='true';
 button.setAttribute('aria-expanded',String(expanding));
 content.hidden=!expanding;
 section.classList.toggle('notice-open',expanding);
}
function currentDateLabel(now=new Date()){
 return new Intl.DateTimeFormat('ru-RU',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now);
}
function updateCurrentDate(){
 const el=document.getElementById('current-date');
 if(el){const now=new Date();el.textContent=currentDateLabel(now);el.dateTime=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;}
}
function render(){const p=activePoint();if(p)pointId=p.id;document.body.className=tab==='settings'?'settings':p?.market||'';const nav=[['calendar','Календарь','calendar-days'],['people','Сотрудники','users'],['network','Вся сеть','layout-grid'],['settings','Настройки','settings']];let h=`<div class="topbar"><div><div class="eyebrow">Управление пунктами выдачи</div><time id="current-date" class="current-date" aria-label="Сегодня">${currentDateLabel()}</time><h2>${tab==='calendar'?'Календарь':tab==='people'?'Команда':tab==='network'?'Вся сеть':tab==='profile'?'Карточка сотрудника':tab==='finance'?'Финансы':'Настройки'}</h2></div><button class="round-add" onclick="openSheet('menu')" aria-label="Добавить">${ico('plus')}</button></div>`;
 if(tab==='calendar'){h+=dashboard(p);h+=unclosedNotice(p?.id);h+=unstaffedNotice(p?.id)}
 h+=`<nav class="main-nav" aria-label="Основные разделы">${nav.map(([k,v,i])=>`<button class="${tab===k?'active':''}" onclick="go('${k}')">${ico(i)}<span>${v}</span></button>`).join('')}</nav>`;
 if(tab!=='settings'&&tab!=='calendar')h+=`<div class="point-switch"><select aria-label="Выбор пункта выдачи" onchange="setPoint(this.value)">${db.points.map(x=>`<option value="${esc(x.id)}" ${x.id===pointId?'selected':''}>${esc(x.name)} · ${MARKET_INFO[x.market]?.name||''}</option>`).join('')||'<option>Сначала добавьте ПВЗ</option>'}</select><button onclick="openSheet('point')" aria-label="Добавить ПВЗ">${ico('plus')}</button></div>`;
 if(tab==='network'){h+=unclosedNotice(null);h+=unstaffedNotice(null)}if(tab==='calendar')h+=calendar(p);if(tab==='people')h+=peopleView();if(tab==='profile')h+=profileView();if(tab==='network')h+=networkView();if(tab==='finance')h+=financeView();if(tab==='settings')h+=settingsView();document.getElementById('app').innerHTML=h;if(tab==='settings'&&settingsQuery)filterSettings(settingsQuery);try{localStorage.setItem(KEY+'-view',JSON.stringify({pointId,networkMarket,settingsQuery}))}catch{}}
function calendar(p){if(!p)return `<div class="card">Добавьте первый ПВЗ, чтобы начать.</div>`;const days=new Date(year,month+1,0).getDate(),off=(new Date(year,month,1).getDay()+6)%7;let h=`<div class="card"><div class="row"><button onclick="moveMonth(-1)">‹</button><b class="grow" style="text-align:center">${new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(year,month,1))}</b><button onclick="moveMonth(1)">›</button></div><div class="calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="weekday">${x}</div>`).join('')}${Array(off).fill('<div></div>').join('')}`;
for(let d=1;d<=days;d++){const ss=shiftAt(p.id,dateStr(d),'employee');const cs=ss.map(s=>person(s.person)?.substitute?'#c9c9c9':person(s.person)?.color||'#ccc');const fill=cs.length?`linear-gradient(90deg,${cs.map((c,i)=>`${c} ${i*100/cs.length}% ${(i+1)*100/cs.length}%`).join(',')})`:'linear-gradient(#fff,#fff)';const borderColors=ss.map(s=>person(s.person)?.substitute?'#888888':person(s.person)?.color||'#999999');const rim=borderColors.length?`linear-gradient(90deg,${borderColors.map((c,i)=>`${c} ${i*100/borderColors.length}% ${(i+1)*100/borderColors.length}%`).join(',')})`:'linear-gradient(#cfcbd2,#cfcbd2)';h+=`<button class="day" style="background:${esc(fill)} padding-box,${esc(rim)} border-box;border:2.5px solid transparent;${bulkSelection&&selectedDates.has(d)?'outline:3px solid #333;outline-offset:1px;':''}" onclick="dayView(${d})">${d}</button>`}h+=`</div><div class="calendar-tools"><div class="tools-title">Управление календарём</div><div class="tools-grid"><button onclick="copyPrevious()">Копировать месяц</button><button onclick="toggleBulk()">${bulkSelection?'Завершить выбор':'Выбрать даты'}</button><button onclick="undoLast()" ${undo.length?'':'disabled'}>Отменить</button><button onclick="redoLast()" ${redo.length?'':'disabled'}>Вернуть</button><button onclick="exportCsv()">Скачать CSV</button><button onclick="exportExcel()">Excel (.xlsx)</button><button onclick="exportPdf()">PDF / печать</button><button onclick="calendarCopySheet()">Копировать по правилу</button></div>${bulkSelection?`<p class="muted">Отметьте даты прямо в календаре. Выбрано: ${selectedDates.size}</p><button class="primary wide" onclick="bulk()" ${selectedDates.size?'':'disabled'}>Назначить сотрудника на выбранные даты</button><div class="tools-grid" style="margin-top:9px"><button onclick="bulkMarkWorked()">Отметить отработанными</button><button onclick="bulkRemovePlanned()">Удалить плановые смены</button><button onclick="bulkMoveSheet()">Перенести смены</button><button onclick="bulkReplaceSheet()">Заменить сотрудника</button></div>`:''}</div></div>`;
h+=`<div class="card legend"><b>Сотрудники и цвета</b><div class="legend-grid">${db.people.filter(x=>!x.archived&&x.role==='employee'&&(db.shifts.some(s=>s.point===p.id&&s.person===x.id)||!x.points?.length||x.points.includes(p.id))).map(x=>`<div class="legend-item"><span class="legend-swatch" style="background:${x.substitute?'#c9c9c9':esc(x.color||'#aaa')};border-color:${x.substitute?'#888':esc(x.color||'#aaa')}"></span>${esc(x.name)}${x.substitute?' · подмена':''}</div>`).join('')||'<span class="muted">Пока нет назначенных сотрудников</span>'}</div></div>`;const managers=db.people.filter(x=>x.role==='manager'&&((x.points||[]).includes(p.id)||db.shifts.some(s=>s.point===p.id&&s.person===x.id)));if(managers.length){h+=`<div class="card"><b>Управляющие</b><div class="muted">Отдельный календарь назначенных управляющих</div><div class="calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="weekday">${x}</div>`).join('')}${Array(off).fill('<div></div>').join('')}`;for(let d=1;d<=days;d++){const s=shiftAt(p.id,dateStr(d),'manager');h+=`<button class="day" style="background:${s.length?'#d4d4d4':'white'};border:2.5px solid ${s.length?'#888888':'#cfcbd2'}" onclick="dayView(${d})">${d}</button>`}h+='</div></div>'}return h}
function dayView(d){if(bulkSelection){selectedDates.has(d)?selectedDates.delete(d):selectedDates.add(d);render();return}selectedDay=dateStr(d);openSheet('day')}
function toggleBulk(){bulkSelection=!bulkSelection;selectedDates.clear();render()}
function peopleView(){return `<div class="card"><div class="row"><h3 class="grow">Персонал</h3><button class="primary" onclick="addPerson()">${ico('plus')} Добавить</button></div>${db.people.map(x=>`<div class="listitem"><div class="row"><span style="display:inline-block;background:${esc(x.substitute?'#bbb':x.color)};width:14px;height:14px;border-radius:4px"></span><button class="person-link grow" onclick="openProfile('${x.id}')">${esc(x.name)}</button><span class="pill">${x.role==='manager'?'Управляющий':x.substitute?'Подменный':'Сотрудник'}</span></div><div class="muted">Ставка: ${Number(x.rate||0).toLocaleString('ru-RU')} ₽ · ${x.archived?'Архив':'Активен'}</div><div class="row"><button onclick="openProfile('${x.id}')">Карточка</button><button onclick="scheduleSheet('${x.id}')">График</button><button onclick="editRate('${x.id}')">Ставки</button>${x.role==='manager'?`<button onclick="assignManager('${x.id}')">Назначить на ПВЗ</button>`:''}<button onclick="toggleArchive('${x.id}')">${x.archived?'Восстановить':'В архив'}</button></div></div>`).join('')||'<p>Пока нет сотрудников.</p>'}</div>`}
function openProfile(pid){profileId=pid;go('profile')}
function profileView(){const w=person(profileId);if(!w)return '<div class="card">Сотрудник не найден. <button onclick="go(\'people\')">Назад</button></div>';const p=activePoint(),prefix=monthPrefix(),all=db.shifts.filter(s=>s.person===w.id&&s.date.startsWith(prefix)),actual=all.filter(s=>s.actual),paid=db.payments.filter(x=>x.person===w.id&&x.date.startsWith(prefix)).reduce((n,x)=>n+x.amount,0),earned=roundMoney(actual.reduce((n,s)=>n+(shiftEarned(s)),0)),reviews=(db.reviews||[]).filter(r=>r.person===w.id&&r.date.startsWith(prefix)),negative=reviews.reduce((n,r)=>n+r.negative,0),threshold=Number(p?.negativeThreshold||3),days=new Date(year,month+1,0).getDate(),off=(new Date(year,month,1).getDay()+6)%7;let h=`<div class="card"><button onclick="go('people')">← Все сотрудники</button><h2>${esc(w.name)}</h2><p class="muted">${w.role==='manager'?'Управляющий':w.substitute?'Подменный сотрудник':'Сотрудник'} · ${w.archived?'В архиве':'Активен'}</p><div class="metric-grid"><div><small>Отработано смен</small><strong>${actual.length}</strong></div><div><small>Начислено</small><strong>${earned.toLocaleString('ru-RU')} ₽</strong></div><div><small>Выплачено за месяц</small><strong>${paid.toLocaleString('ru-RU')} ₽</strong></div><div><small>Разница за период</small><strong>${roundMoney(earned-paid).toLocaleString('ru-RU')} ₽</strong></div></div><div class="row"><button onclick="scheduleSheet('${w.id}')">Заполнить график</button><button onclick="editRate('${w.id}')">Ставки</button><button onclick="reviewSheet('${w.id}')">Добавить оценку</button></div></div>`;
h+=`<div class="card"><h3>Личный календарь · ${new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(year,month,1))}</h3><div class="row"><button onclick="moveMonth(-1)">←</button><button onclick="moveMonth(1)">→</button></div><div class="calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="weekday">${x}</div>`).join('')}${Array(off).fill('<div></div>').join('')}`;for(let d=1;d<=days;d++){const ds=dateStr(d),shift=all.find(s=>s.date===ds);h+=`<button class="day" style="background:${shift?(w.substitute?'#c9c9c9':esc(w.color||'#ccc')):'#fff'};border-color:${shift?esc(w.color||'#999'):'#cfcbd2'}" onclick="selectedDay='${ds}';openSheet('day')">${d}</button>`}h+='</div></div>';
h+=`<div class="card"><h3>Оценки и отзывы</h3><p class="${negative>=threshold?'review-warning':'muted'}">Негативных отзывов за месяц: <b>${negative}</b>. Порог предупреждения: ${threshold}</p>${reviews.map(r=>`<div class="listitem">${esc(r.date)} · оценка ${r.rating}/5 · негативных отзывов: ${r.negative}${r.comment?' · '+esc(r.comment):''}</div>`).join('')||'<p class="muted">Оценок пока нет</p>'}<button onclick="reviewSheet('${w.id}')">Добавить оценку</button></div>`;
h+=`<div class="card"><h3>История происшествий</h3>${db.incidents.filter(q=>q.person===w.id).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30).map(q=>`<div class="listitem">${esc(q.date)} · ${esc(q.type)} · ${q.amount} ₽ · ${esc(q.status)}<div class="row"><button onclick="incidentDetail('${q.id}')">Подробнее / погашения</button></div></div>`).join('')||'<p class="muted">Происшествий нет</p>'}</div>`;h+=`<div class="card"><h3>Учёт погашений по происшествиям</h3><p class="muted">Отдельный справочный учёт. Не является разрешением удерживать деньги из зарплаты и не влияет на зарплатную ведомость.</p>${db.incidents.filter(q=>q.person===w.id&&q.amount>0).map(q=>`<div class="listitem"><b>${esc(q.type)}</b> · ${esc(q.date)}<div>Сумма: ${q.amount.toLocaleString('ru-RU')} ₽ · учтено погашений: ${incidentRepaid(q.id).toLocaleString('ru-RU')} ₽ · остаток: ${roundMoney(q.amount-incidentRepaid(q.id)).toLocaleString('ru-RU')} ₽</div><button onclick="incidentDetail('${q.id}')">История и график платежей</button></div>`).join('')||'<p class="muted">Нет происшествий с суммой.</p>'}</div>`;return h}
function incidentRepaid(iid){return roundMoney((db.repayments||[]).filter(r=>r.incident===iid).reduce((a,r)=>a+r.amount,0))}
function incidentDetail(iid){const q=db.incidents.find(x=>x.id===iid);if(!q)return;sheetKind='incident-detail';const paid=incidentRepaid(iid),left=roundMoney(q.amount-paid);const history=(db.repayments||[]).filter(r=>r.incident===iid).sort((a,b)=>a.date.localeCompare(b.date));document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true" aria-label="Учёт происшествия"><div class="sheet-head"><h3>${esc(q.type)} · ${esc(person(q.person)?.name||'')}</h3><button class="sheet-close" onclick="closeSheet()">${ico('close')}</button></div><p>${esc(q.date)} · ${esc(q.status)}${q.barcode?' · ШК: '+esc(q.barcode):''}</p><div class="ledger-box"><div>Сумма происшествия: <b>${q.amount.toLocaleString('ru-RU')} ₽</b></div><div>Учтено погашений: <b>${paid.toLocaleString('ru-RU')} ₽</b></div><div>Осталось по записи: <b>${left.toLocaleString('ru-RU')} ₽</b></div></div><p class="muted">Справочный учёт согласованных и фактически произведённых погашений. Не списывает зарплату автоматически. Законность любых удержаний необходимо подтверждать отдельно.</p><h4>График платежей</h4>${installmentView(iid)}<button class="primary wide" onclick="installmentSheet('${iid}')">Создать / изменить график рассрочки</button><h4>История фактических погашений</h4>${history.map(r=>`<div class="listitem">${esc(r.date)} · ${r.amount.toLocaleString('ru-RU')} ₽ ${r.note?'· '+esc(r.note):''}<button onclick="removeRepayment('${r.id}','${iid}')">Удалить запись</button></div>`).join('')||'<p class="muted">Пока нет записей.</p>'}${left>0?`<form onsubmit="submitRepayment(event,'${iid}')">${field('Сумма фактического погашения, ₽','amount','number',`required min="0.01" max="${left}" step="0.01"`)}${field('Дата (ГГГГ-ММ-ДД)','date','text',`required value="${new Date().toLocaleDateString('sv-SE')}" pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}"`)}${field('Основание / примечание','note','text','maxlength="500" placeholder="Например, добровольное возмещение"')}<button class="primary wide">Записать погашение</button></form>`:'<p>Сумма по записи погашена полностью.</p>'}<div id="sheet-error" class="sheet-error" role="alert"></div></section>`;setupSheetKeyboard()}
function submitRepayment(e,iid){e.preventDefault();const q=db.incidents.find(x=>x.id===iid);if(!q)return;const f=new FormData(e.currentTarget),amount=roundMoney(Number(f.get('amount'))),date=String(f.get('date')||''),note=String(f.get('note')||'').trim();if(!amountValid(amount)||!dateValid(date)||note.length>500||amount>roundMoney(q.amount-incidentRepaid(iid)))return sheetError('Проверьте дату и сумму: она не должна превышать остаток.');if(commit(()=>{db.repayments=db.repayments||[];db.repayments.push({id:id(),incident:iid,point:q.point,person:q.person,amount,date,note})}))incidentDetail(iid)}
function removeRepayment(rid,iid){if(!confirm('Удалить запись погашения?'))return;if(commit(()=>db.repayments=db.repayments.filter(r=>r.id!==rid)))incidentDetail(iid)}
function reviewSheet(pid){const w=person(pid);if(!w)return;sheetKind='review';document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>Оценка · ${esc(w.name)}</h3><button class="sheet-close" onclick="closeSheet()">${ico('close')}</button></div><form onsubmit="submitReview(event,'${pid}')">${selectField('Оценка','rating',[1,2,3,4,5].map(n=>[String(n),String(n)+' из 5']))}${field('Количество негативных отзывов','negative','number','min="0" max="100000" step="1" value="0" required')}${field('Дата','date','text',`value="${new Date().toLocaleDateString('sv-SE')}" required pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}"`)}${field('Комментарий','comment')}<button class="primary wide">Сохранить</button></form><div id="sheet-error" class="sheet-error"></div></section>`;setupSheetKeyboard()}
function submitReview(e,pid){e.preventDefault();const f=new FormData(e.target),negative=Number(f.get('negative')),rating=Number(f.get('rating')),date=String(f.get('date')),point=activePoint()?.id;if(!point||!dateValid(date)||!Number.isInteger(negative)||negative<0||negative>100000)return sheetError('Проверьте дату и число отзывов');if(commit(()=>{db.reviews=db.reviews||[];db.reviews.push({id:id(),person:pid,point,date,negative,rating,comment:String(f.get('comment')||'')})})){closeSheet();go('profile')}}
function thresholdSheet(){const p=activePoint();if(!p)return;sheetKind='threshold';document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>Порог негативных отзывов</h3><button onclick="closeSheet()">Закрыть</button></div><form onsubmit="event.preventDefault();const n=Number(new FormData(this).get('threshold'));if(!Number.isInteger(n)||n<1||n>10000)return sheetError('Введите число от 1 до 10000');if(commit(()=>activePoint().negativeThreshold=n))closeSheet()">${field('Предупреждать начиная с','threshold','number',`min="1" max="10000" value="${p.negativeThreshold||3}" required`)}<button class="primary wide">Сохранить</button></form><div id="sheet-error" class="sheet-error"></div></section>`;setupSheetKeyboard()}
function networkView(){
 const points=db.points.filter(p=>networkMarket==='all'||p.market===networkMarket);
 const prefix=monthPrefix()+'-',days=new Date(year,month+1,0).getDate();
 const markets=[['all','Вся сеть'],['wb','Wildberries'],['ozon','Ozon'],['ym','Яндекс Маркет']];
 const filters=markets.filter(([m])=>m==='all'||db.points.some(p=>p.market===m)).map(([m,label])=>`<button type="button" class="network-filter ${networkMarket===m?'active':''}" data-market="${m}" aria-pressed="${networkMarket===m}" onclick="networkMarket='${m}';render()">${esc(label)}</button>`).join('');
 const totals={shifts:0,staff:new Set(),problems:0};
 const cards=points.map(p=>{
  const shifts=db.shifts.filter(s=>s.point===p.id&&s.date.startsWith(prefix));
  const staff=new Set([...shifts.map(s=>s.person),...db.people.filter(w=>!w.archived&&w.points?.includes(p.id)).map(w=>w.id)]);
  const problems=db.incidents.filter(x=>x.point===p.id&&x.status!=='отменено'&&x.status!=='подтверждено').length;
  totals.shifts+=shifts.length;staff.forEach(x=>totals.staff.add(x));totals.problems+=problems;
  const market=MARKET_INFO[p.market]||{name:'ПВЗ'};
  return `<article class="network-point-card" data-market="${esc(p.market)}"><div class="network-point-head"><div class="network-point-kicker">${esc(market.name)}</div>${marketStoreIcon(p.market)}</div><h3>${esc(p.name)}</h3><div class="network-point-stats"><span>${ico('calendar-days')} ${shifts.length} смен</span><span>${ico('users')} ${staff.size} сотрудников</span><span>${ico('alert')} ${problems} проблем</span></div><button type="button" class="network-open" onclick="setPoint('${p.id}');go('calendar')">Открыть ПВЗ ${ico('arrow-right')}</button></article>`;
 }).join('');
 let h=`<section class="network-overview"><div class="network-heading"><div><div class="network-kicker">Панель управления</div><h3>Вся сеть ПВЗ</h3><p>Все пункты и их показатели за выбранный месяц</p></div>${ico('layout-grid')}</div><div class="network-filters" role="group" aria-label="Маркетплейсы">${filters}</div><div class="network-summary"><div><strong>${points.length}</strong><span>Пунктов выдачи</span></div><div><strong>${totals.shifts}</strong><span>Смен в месяце</span></div><div><strong>${totals.staff.size}</strong><span>Сотрудников</span></div><div><strong>${totals.problems}</strong><span>Открытых проблем</span></div></div><div class="network-point-grid">${cards||'<div class="network-empty">Пока нет пунктов выбранного маркетплейса. Добавьте ПВЗ через кнопку «+».</div>'}</div></section>`;
 h+=`<section class="network-calendar card"><div class="network-calendar-title"><div><div class="network-kicker">Планирование</div><h3>Сводный календарь сети</h3></div><div class="network-month"><button onclick="moveMonth(-1)" aria-label="Предыдущий месяц">‹</button><b>${new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(year,month,1))}</b><button onclick="moveMonth(1)" aria-label="Следующий месяц">›</button></div></div><div class="network-scroll"><table class="network-table"><thead><tr><th>ПВЗ</th>${Array.from({length:days},(_,i)=>`<th>${i+1}</th>`).join('')}</tr></thead><tbody>`;
 for(const p of points){h+=`<tr data-market="${esc(p.market)}"><th><button onclick="setPoint('${p.id}');go('calendar')">${esc(p.name)}</button></th>`;for(let d=1;d<=days;d++){const date=prefix+String(d).padStart(2,'0'),ss=shiftAt(p.id,date,'employee');h+=`<td title="${esc(ss.map(s=>person(s.person)?.name).join(', '))}" class="${ss.length?'network-busy':''}">${ss.length||''}</td>`}h+='</tr>'}
 return h+`</tbody></table></div><p class="muted">Число в ячейке — количество назначенных сотрудников. Нажмите название ПВЗ для перехода к его календарю.</p></section>`;
}
// Исторический остаток считается по всем записанным фактическим сменам и выплатам.
// Это расчётная разница, не юридическое признание задолженности.
// Rates are frozen on confirmation of a worked shift. Old shifts retain legacy fallback.
function shiftEarned(s){const w=person(s.person);if(!w)return 0;const hourly=Number(s.hourlyRateSnapshot??w.hourlyRate??0),daily=Number(s.rateSnapshot??w.rate??0);return roundMoney(hourly>0?hourly*Number(s.hours??12):daily)}
function freezeShiftRate(s){const w=person(s.person);if(!w)return;if(s.rateSnapshot===undefined)s.rateSnapshot=Number(w.rate||0);if(s.hourlyRateSnapshot===undefined)s.hourlyRateSnapshot=Number(w.hourlyRate||0)}
function shiftPreview(s){const w=person(s.person);return Number(w?.hourlyRate||0)>0?roundMoney(Number(w.hourlyRate)*(s.hours??12)):Number(w?.rate||0)}
function payrollLedger(pointID,personID,cutoff){
 const who=person(personID);if(!who)return {earned:0,paid:0,balance:0,shifts:0,hours:0};
 const actual=db.shifts.filter(x=>x.point===pointID&&x.person===personID&&x.actual&&x.date<cutoff);
 const earned=roundMoney(actual.reduce((sum,x)=>sum+(shiftEarned(x)),0));
 const paid=roundMoney(db.payments.filter(x=>x.point===pointID&&x.person===personID&&x.date<cutoff).reduce((sum,x)=>sum+Number(x.amount||0),0));
 return {earned,paid,balance:roundMoney(earned-paid),shifts:actual.length,hours:roundMoney(actual.reduce((sum,x)=>sum+(x.hours??12),0))};
}
function ledgerDetail(pointID,personID){
 const prefix=monthPrefix(),start=prefix+'-01',next=new Date(year,month+1,1),end=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-01`;
 const opening=payrollLedger(pointID,personID,start),closing=payrollLedger(pointID,personID,end);
 return {opening,closing,earned:roundMoney(closing.earned-opening.earned),paid:roundMoney(closing.paid-opening.paid)};
}
function payrollView(p){if(!p)return '';const prefix=monthPrefix(),ids=new Set([...db.shifts.filter(s=>s.point===p.id&&s.date.startsWith(prefix)).map(s=>s.person),...db.payments.filter(x=>x.point===p.id&&x.date.startsWith(prefix)).map(x=>x.person)]);let h=`<div class="row"><h3 class="grow">Зарплата · ${prefix}</h3><button onclick="exportPayrollCsv()">Скачать расчёт CSV</button></div><p class="muted">Начисление по подтверждённым фактическим сменам. Плановые показаны отдельно и не считаются долгом по зарплате. Претензии и штрафы не вычитаются автоматически. Расчётный остаток учитывает предыдущие месяцы, но не является юридически подтверждённым долгом. Новые отработанные смены фиксируют ставку на дату подтверждения. Ранее подтверждённые смены без сохранённой ставки рассчитываются по текущей ставке; проверяйте их вручную.</p>`;for(const pid of ids){const who=person(pid);if(!who)continue;const shifts=db.shifts.filter(s=>s.point===p.id&&s.person===pid&&s.date.startsWith(prefix)),actual=shifts.filter(s=>s.actual),planned=shifts.filter(s=>!s.actual);const rate=Number(who.rate||0),hourly=Number(who.hourlyRate||0);const earned=roundMoney(actual.reduce((n,s)=>n+(shiftEarned(s)),0));const estimate=roundMoney(planned.reduce((n,s)=>n+(shiftPreview(s)),0));const paid=roundMoney(db.payments.filter(x=>x.point===p.id&&x.person===pid&&x.date.startsWith(prefix)).reduce((n,x)=>n+x.amount,0));h+=`<div class="listitem"><b>${esc(who.name)}</b><div class="muted">Фактически: ${actual.length} · запланировано: ${planned.length} · ставка: ${rate.toLocaleString('ru-RU')} ₽/смена${hourly?' · '+hourly+' ₽/час':''}</div><div>Начислено по факту: <b>${earned.toLocaleString('ru-RU')} ₽</b></div><div>Прогноз по плану: ${estimate.toLocaleString('ru-RU')} ₽</div><div>Выплачено в этом месяце: ${paid.toLocaleString('ru-RU')} ₽</div><div class="muted">Из них авансы: ${roundMoney(db.payments.filter(x=>x.point===p.id&&x.person===pid&&x.date.startsWith(prefix)&&x.kind==='advance').reduce((n,x)=>n+x.amount,0)).toLocaleString('ru-RU')} ₽</div><div>Разница за выбранный месяц: <b>${roundMoney(earned-paid).toLocaleString('ru-RU')} ₽</b></div><div class="ledger-box"><div>Остаток на начало месяца: <b>${ledgerDetail(p.id,pid).opening.balance.toLocaleString('ru-RU')} ₽</b></div><div>Расчётный остаток на конец месяца: <b>${ledgerDetail(p.id,pid).closing.balance.toLocaleString('ru-RU')} ₽</b></div></div></div>`}return h+(ids.size?'':'<p>Нет смен или выплат в этом месяце.</p>')}
function financeView(){const p=activePoint();return `<div class="card">${payrollView(p)}<hr><h3>Начисления и проблемы</h3><button onclick="addIncident()">+ Проблема / доплата</button><button onclick="addPayment()">+ Выплата</button>${db.incidents.filter(x=>!p||x.point===p.id).map(x=>`<div class="listitem">${esc(x.type)} · ${esc(person(x.person)?.name)} · ${x.amount} ₽ · ${esc(x.status)}<div class="muted">${esc(x.barcode||'')} ${esc(x.date)}</div><button onclick="resolveIncident('${x.id}')">Изменить статус</button></div>`).join('')}${db.payments.filter(x=>!p||x.point===p.id).map(x=>`<div class="listitem">${x.kind==='advance'?'Аванс':x.kind==='other'?'Другая выплата':'Зарплата'}: ${esc(person(x.person)?.name)} · ${x.amount} ₽ · ${esc(x.date)}</div>`).join('')}</div>`}
function settingsView(){
 const p=activePoint(), cfg=db.settings||{}, hours=Number.isFinite(Number(cfg.defaultHours))?Number(cfg.defaultHours):12;
 const groups=[
 {icon:'settings',title:'Интерфейс',desc:'Настройте удобный способ работы',key:'режим интерфейс простой стандартный расширенный',body:`<label class="form-field"><span>Режим приложения</span><select onchange="changeMode(this.value)">${[['simple','Простой'],['standard','Стандартный'],['advanced','Расширенный']].map(([v,n])=>`<option value="${v}" ${cfg.mode===v?'selected':''}>${n}</option>`).join('')}</select></label><p class="settings-tip">Режим меняет только отображение инструментов. Все данные сохраняются.</p>`},
 {icon:'store',title:'Пункты выдачи',desc:'Названия, маркетплейсы и параметры пунктов',key:'пвз пункты адрес название маркетплейс',body:`${db.points.length?`<div class="settings-point-list">${db.points.map(x=>`<div class="settings-point-row"><span class="settings-market-dot ${esc(x.market)}"></span><div class="grow"><strong>${esc(x.name)}</strong><small>${esc(MARKET_INFO[x.market]?.name||'ПВЗ')}</small></div><button type="button" onclick="editPointSettings('${esc(x.id)}')">Изменить</button></div>`).join('')}</div>`:'<p class="settings-tip">Пока нет добавленных пунктов.</p>'}<button type="button" class="settings-secondary" onclick="addPoint()">${ico('plus')} Добавить ПВЗ</button>`},
 {icon:'calendar-days',title:'Календарь и смены',desc:'Длительность смен и отображение календаря',key:'календарь смены часы график',body:`<form onsubmit="saveAppSettings(event)"><label class="form-field"><span>Часов в смене по умолчанию</span><input name="defaultHours" type="number" inputmode="decimal" min="0.25" max="24" step="0.25" value="${hours}" required></label><p class="settings-tip">Применяется к новым отметкам «Отработана». Уже подтверждённые часы не меняются.</p><button class="primary">Сохранить параметры</button></form>`},
 {icon:'alert',title:'Предупреждения о пустых сменах',desc:'За сколько дней предупреждать об отсутствии сотрудников',key:'предупреждения уведомления свободные даты пустые смены график диапазон',body:`<form onsubmit="saveVacantShiftSettings(event)"><label class="form-field"><span>Проверять ближайшие дни (включая сегодня)</span><input name="vacantShiftAlertDays" type="number" inputmode="numeric" min="0" max="90" step="1" value="${Number.isInteger(Number(cfg.vacantShiftAlertDays))&&Number(cfg.vacantShiftAlertDays)>=0&&Number(cfg.vacantShiftAlertDays)<=90?Number(cfg.vacantShiftAlertDays):7}" required></label><p class="settings-tip">Например, 14 — покажет дни без сотрудников на ближайшие две недели. 0 — отключить предупреждения. Проверяются все ПВЗ, а не только открытый.</p><button class="primary">Сохранить период</button></form>`},
 {icon:'users',title:'Оценки и отзывы',desc:'Предупреждения для сотрудников по каждому ПВЗ',key:'оценки отзывы негативные порог предупреждение',body:`${p?`<p class="settings-tip">Выбранный ПВЗ: <b>${esc(p.name)}</b>. Порог предупреждения о негативных отзывах настраивается отдельно для каждого пункта.</p><button type="button" class="settings-secondary" onclick="thresholdSheet()">Настроить порог отзывов</button>`:'<p class="settings-tip">Сначала добавьте ПВЗ.</p>'}`},
 {icon:'wallet',title:'Зарплаты и выплаты',desc:'Расчёты, ведомости и история выплат',key:'зарплаты выплаты финансы ведомость excel csv',body:`<p class="settings-tip">Начисления учитываются по подтверждённым сменам. Штрафы и претензии автоматически из зарплаты не удерживаются.</p><div class="settings-actions"><button type="button" onclick="go('finance')">Открыть финансы</button><button type="button" onclick="exportPayrollCsv()">Скачать ведомость CSV</button></div>`},
 {icon:'download',title:'Экспорт и печать',desc:'Выгрузка календаря и данных',key:'экспорт excel pdf csv печать скачать',body:`<div class="settings-actions"><button type="button" onclick="exportExcel()">Excel (.xlsx)</button><button type="button" onclick="exportPdf()">PDF через печать</button><button type="button" onclick="exportCsv()">CSV</button></div><p class="settings-tip">PDF сохраняется через системное меню печати.</p>`},
 {icon:'download',title:'Резервные копии',desc:'Сохранение и восстановление локальных данных',key:'архив резервная копия json восстановление данные',body:`<div class="settings-actions"><button type="button" onclick="backup()">Скачать резервную копию JSON</button><label class="settings-file">Восстановить из JSON<input type="file" accept="application/json,.json" onchange="restore(this.files[0])" hidden></label></div><p class="settings-tip">Восстановление заменяет локальную базу после подтверждения. Сначала сохраните копию.</p>`},
 {icon:'alert',title:'Хранение и безопасность',desc:'Состояние подключения и ограничения',key:'синхронизация безопасность сервер облако telegram',body:`<div class="settings-status"><span class="settings-status-dot"></span><div><strong>Состояние хранения</strong><small>Текущий статус и управление синхронизацией — внизу страницы.</small></div></div><p class="settings-tip">До появления статуса «Синхронизировано» данные хранятся только на устройстве. Регулярно сохраняйте резервную копию.</p>`}
 ];
 return `<section class="settings-page"><div class="settings-hero"><div class="settings-hero-icon">${ico('settings')}</div><div><span class="settings-overline">Персонализация</span><h3>Настройки</h3><p>Все параметры приложения в одном месте</p></div></div><label class="settings-search"><span>${ico('search')}</span><input id="settings-search-input" aria-label="Поиск настроек" placeholder="Найти настройку…" value="${esc(settingsQuery)}" oninput="filterSettings(this.value)"></label><p id="settings-notice" class="settings-notice" hidden role="status"></p><div class="settings-groups">${groups.map(g=>`<article class="settings-group" data-setting="${esc(g.key+' '+g.title+' '+g.desc)}"><div class="settings-group-head"><span class="settings-group-icon">${ico(g.icon)}</span><div><h4>${g.title}</h4><p>${g.desc}</p></div></div><div class="settings-group-body">${g.body}</div></article>`).join('')}</div><p id="settings-empty" class="settings-no-results" hidden>По вашему запросу ничего не найдено.</p></section>`;
}
function filterSettings(q){settingsQuery=String(q||'').toLowerCase().trim();let found=0;document.querySelectorAll('.settings-group[data-setting]').forEach(el=>{const yes=el.dataset.setting.includes(settingsQuery);el.hidden=!yes;if(yes)found++});const empty=document.getElementById('settings-empty');if(empty)empty.hidden=found>0;try{localStorage.setItem(KEY+'-view',JSON.stringify({pointId,networkMarket,settingsQuery}))}catch{}}
function saveAppSettings(e){e.preventDefault();const f=new FormData(e.currentTarget),h=Number(f.get('defaultHours'));if(!Number.isFinite(h)||h<0.25||h>24){sheetErrorSafe('Укажите от 0,25 до 24 часов.');return}if(commit(()=>{db.settings=db.settings||{};db.settings.defaultHours=h}))showSettingsNotice('Параметры сохранены')}
function saveVacantShiftSettings(e){e.preventDefault();const n=Number(new FormData(e.currentTarget).get('vacantShiftAlertDays'));if(!Number.isInteger(n)||n<0||n>90){showSettingsNotice('Введите целое число от 0 до 90.');return}if(commit(()=>{db.settings=db.settings||{};db.settings.vacantShiftAlertDays=n}))showSettingsNotice(n===0?'Предупреждения о пустых сменах отключены.':`Период предупреждений: ${n} дн.`)}
function showSettingsNotice(message){const el=document.getElementById('settings-notice');if(el){el.textContent=message;el.hidden=false}}
function editPointSettings(pid){const p=db.points.find(x=>x.id===pid);if(!p)return;sheetKind='point-settings';document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>Настройки ПВЗ</h3><button class="sheet-close" onclick="closeSheet()" aria-label="Закрыть">${ico('close')}</button></div><form onsubmit="submitPointSettings(event,'${esc(pid)}')">${field('Название или адрес','name','text',`required maxlength="120" value="${esc(p.name)}"`)}${selectField('Маркетплейс','market',[['wb','Wildberries'],['ozon','Ozon'],['ym','Яндекс Маркет']])}<p class="settings-tip">Смена маркетплейса меняет оформление и категории новых происшествий, но не удаляет старые записи.</p><button class="primary wide">Сохранить изменения</button></form><div id="sheet-error" class="sheet-error" role="alert"></div></section>`;setupSheetKeyboard();document.querySelector('#sheet-root [name="market"]').value=p.market}
function submitPointSettings(e,pid){e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')||'').trim(),market=String(f.get('market')||'');if(!name||name.length>120||!['wb','ozon','ym'].includes(market))return sheetError('Проверьте название и маркетплейс.');if(commit(()=>{const p=db.points.find(x=>x.id===pid);if(!p)throw Error('ПВЗ не найден');p.name=name;p.market=market})){closeSheet();render()}}

function changeMode(mode){commit(()=>{db.settings.mode=mode})}function go(t){tab=t;render()}function moveMonth(n){month+=n;if(month<0){month=11;year--}if(month>11){month=0;year++}render()}
function addPoint(){openSheet('point')}
function addPerson(){openSheet('person')}
function editRate(pid){const x=person(pid);if(!x)return;sheetKind='rate';document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>Ставка · ${esc(x.name)}</h3><p class="muted">Изменения применяются к новым отработанным сменам. Ставки ранее подтверждённых смен сохраняются.</p><button onclick="closeSheet()">Закрыть</button></div><form onsubmit="event.preventDefault();const f=new FormData(this),a=Number(f.get('rate')),b=Number(f.get('hourly'));if(!amountValid(a,true)||!amountValid(b,true))return sheetError('Проверьте суммы');if(commit(()=>{const w=person('${pid}');w.rate=a;w.hourlyRate=b}))closeSheet()">${field('За смену, ₽','rate','number',`min="0" step="0.01" value="${x.rate||0}"`)}${field('За час, ₽ (0 — по сменам)','hourly','number',`min="0" step="0.01" value="${x.hourlyRate||0}"`)}<button class="primary wide">Сохранить</button></form><div id="sheet-error" class="sheet-error"></div></section>`;setupSheetKeyboard()}

function toggleArchive(pid){commit(()=>{const p=person(pid);p.archived=!p.archived})}
function assignManager(pid){const p=activePoint();if(!p)return;commit(()=>{const x=person(pid);x.points=x.points||[];if(!x.points.includes(p.id))x.points.push(p.id)})}
function autoSchedule(pid){scheduleSheet(pid)}
function copyPrevious(){calendarCopySheet()}
function bulk(){const p=activePoint();if(!p||!selectedDates.size)return;const opts=staffOptions();if(!opts.length){openSheet('person');return}sheetKind='bulk';const dates=[...selectedDates].sort((a,b)=>a-b);document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>Назначить смены</h3><button class="sheet-close" onclick="closeSheet()">${ico('close')}</button></div><p>Выбрано дат: <b>${dates.join(', ')}</b></p><form onsubmit="submitBulk(event)">${selectField('Сотрудник','person',opts)}<button class="primary wide" type="submit">Назначить на ${dates.length} дат</button></form><div id="sheet-error" class="sheet-error" role="alert"></div></section>`;setupSheetKeyboard()}
function submitBulk(e){e.preventDefault();const p=activePoint(),pid=new FormData(e.target).get('person');const dates=[...selectedDates].map(dateStr),changes=dates.filter(date=>!db.shifts.some(s=>s.point===p.id&&s.person===pid&&s.date===date)).map(date=>({id:id(),point:p.id,person:pid,date,actual:false}));if(!changes.length)return sheetError('Все выбранные смены уже назначены.');if(!ensureNoConflicts(changes))return sheetError('Есть пересечения с другим ПВЗ.');if(commit(()=>db.shifts.push(...changes))){bulkSelection=false;selectedDates.clear();closeSheet();render()}}
function bulkMarkWorked(){
 const p=activePoint();if(!p||!selectedDates.size)return;
 const dates=new Set([...selectedDates].map(dateStr));
 const matching=db.shifts.filter(s=>s.point===p.id&&dates.has(s.date)&&!s.actual);
 if(!matching.length){alert('На выбранных датах нет неотмеченных смен.');return}
 if(!confirm(`Отметить отработанными ${matching.length} смен? Для каждой будет установлено 12 часов; их можно изменить в карточке дня.`))return;
 if(commit(()=>{for(const s of matching){s.actual=true;s.hours=s.hours??(Number(db.settings?.defaultHours)||12);freezeShiftRate(s)}})){selectedDates.clear();bulkSelection=false;render()}
}
function bulkRemovePlanned(){
 const p=activePoint();if(!p||!selectedDates.size)return;
 const dates=new Set([...selectedDates].map(dateStr));
 const ids=new Set(db.shifts.filter(s=>s.point===p.id&&dates.has(s.date)&&!s.actual).map(s=>s.id));
 if(!ids.size){alert('На выбранных датах нет плановых смен для удаления. Отработанные смены не затрагиваются.');return}
 if(!confirm(`Удалить ${ids.size} плановых смен? Отработанные смены сохранятся. Действие можно отменить.`))return;
 if(commit(()=>{db.shifts=db.shifts.filter(s=>!ids.has(s.id))})){selectedDates.clear();bulkSelection=false;render()}
}
// Графики рассрочки являются справочными и не создают автоматических удержаний.
function installmentView(iid){const plan=(db.installments||[]).find(x=>x.incident===iid);if(!plan)return '<p class="muted">График пока не создан.</p>';const repayments=db.repayments.filter(x=>x.incident===iid).sort((a,b)=>a.date.localeCompare(b.date));let paid=0;const today=new Date().toLocaleDateString('sv-SE');return `<div class="ledger-box"><div>Основание: ${plan.basis==='voluntary'?'добровольное погашение':'справочный план'}</div><div>Статус: ${plan.status==='active'?'действует':plan.status==='paused'?'приостановлен':'закрыт'}</div><div>Запланировано: ${plan.total.toLocaleString('ru-RU')} ₽</div>${plan.schedule.map((row,i)=>{const before=paid;paid+=row.amount;const received=roundMoney(repayments.filter(r=>r.date<=row.date).reduce((n,r)=>n+r.amount,0));const due=roundMoney(Math.max(0,paid-received));return `<div class="listitem"><b>${i+1}. ${esc(row.date)}</b> · ${row.amount.toLocaleString('ru-RU')} ₽ <span class="${row.date<today&&due>0?'review-warning':'muted'}">${due<=0?'погашено по графику':row.date<today?'просрочено '+due.toLocaleString('ru-RU')+' ₽':'остаток к сроку '+due.toLocaleString('ru-RU')+' ₽'}</span></div>`}).join('')}</div>`}
function installmentSheet(iid){const q=db.incidents.find(x=>x.id===iid);if(!q)return;const plan=(db.installments||[]).find(x=>x.incident===iid),remaining=roundMoney(q.amount-incidentRepaid(iid));sheetKind='installment';const today=new Date().toLocaleDateString('sv-SE');document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>График платежей</h3><button class="sheet-close" onclick="closeSheet()">${ico('close')}</button></div><p class="muted">Не является согласием на удержание из зарплаты. Суммы фактических платежей записываются отдельно.</p><form onsubmit="saveInstallment(event,'${iid}')">${field('Сумма плана, ₽','total','number',`required min="0.01" max="${q.amount}" step="0.01" value="${plan?.total||remaining}"`)}${field('Первый платёж (ГГГГ-ММ-ДД)','first','text',`required pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}" value="${plan?.schedule[0]?.date||today}"`)}${field('Количество платежей','count','number',`required min="1" max="120" step="1" value="${plan?.schedule.length||3}"`)}${selectField('Интервал','interval',[['month','Каждый месяц'],['week','Каждую неделю'],['14days','Каждые 14 дней']])}${selectField('Основание','basis',[['informational','Справочный график'],['voluntary','Добровольное погашение (подтверждается отдельно)']])}${selectField('Состояние','status',[['active','Действует'],['paused','Приостановлен'],['closed','Закрыт']])}<button class="primary wide">Сохранить график</button></form><div id="sheet-error" class="sheet-error"></div></section>`;setupSheetKeyboard();if(plan){document.querySelector('[name=basis]').value=plan.basis;document.querySelector('[name=status]').value=plan.status;document.querySelector('[name=interval]').value=plan.interval||'month'}}
function saveInstallment(e,iid){e.preventDefault();const q=db.incidents.find(x=>x.id===iid),f=new FormData(e.target),total=roundMoney(Number(f.get('total'))),count=Number(f.get('count')),first=String(f.get('first')),interval=String(f.get('interval')),basis=String(f.get('basis')),status=String(f.get('status'));if(!q||!amountValid(total)||total>q.amount||!Number.isInteger(count)||count<1||count>120||!dateValid(first))return sheetError('Проверьте сумму, дату и число платежей.');const cents=Math.round(total*100),base=Math.floor(cents/count),rest=cents%count;const schedule=[];for(let i=0;i<count;i++){const d=new Date(first+'T12:00:00Z');if(interval==='month'){const day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+i);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last))}else d.setUTCDate(d.getUTCDate()+i*(interval==='week'?7:14));schedule.push({date:d.toISOString().slice(0,10),amount:(base+(i<rest?1:0))/100})}if(schedule.some(x=>!amountValid(x.amount)))return sheetError('Слишком много платежей для этой суммы.');const existing=(db.installments||[]).find(x=>x.incident===iid);if(commit(()=>{db.installments=db.installments||[];db.installments=db.installments.filter(x=>x.incident!==iid);db.installments.push({id:existing?.id||id(),incident:iid,point:q.point,person:q.person,total,count,interval,basis,status,schedule})}))incidentDetail(iid)}
function bulkMoveSheet(){bulkEditSheet('move')}
function bulkReplaceSheet(){bulkEditSheet('replace')}
function bulkEditSheet(mode){const p=activePoint();if(!p||!selectedDates.size)return;const dates=new Set([...selectedDates].map(dateStr));const candidates=db.shifts.filter(s=>s.point===p.id&&dates.has(s.date)&&!s.actual);if(!candidates.length)return alert('На выбранных датах нет плановых смен.');sheetKind='bulk-edit';const options=staffOptions();document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>${mode==='move'?'Перенести смены':'Заменить сотрудника'}</h3><button onclick="closeSheet()">Закрыть</button></div><p class="muted">Изменяются только плановые смены. Отработанные не затрагиваются.</p><form onsubmit="submitBulkEdit(event,'${mode}')">${selectField('Чьи смены','source',[['all','Все выбранные'],...options])}${mode==='move'?field('Сдвинуть на дней (от −31 до 31)','offset','number','required min="-31" max="31" step="1" value="1"'):selectField('Новый сотрудник','target',options)}<button class="primary wide">Применить</button></form><div id="sheet-error" class="sheet-error"></div></section>`;setupSheetKeyboard()}
function submitBulkEdit(e,mode){e.preventDefault();const p=activePoint(),f=new FormData(e.target),dates=new Set([...selectedDates].map(dateStr)),source=f.get('source'),target=f.get('target'),offset=Number(f.get('offset'));const selected=db.shifts.filter(s=>s.point===p.id&&dates.has(s.date)&&!s.actual&&(source==='all'||s.person===source));if(!selected.length)return sheetError('Не найдено смен для изменения.');if(mode==='move'&&(!Number.isInteger(offset)||Math.abs(offset)>31||offset===0))return sheetError('Укажите сдвиг от −31 до 31 дней, кроме нуля.');if(mode==='replace'&&(!person(target)||person(target).archived))return sheetError('Выберите сотрудника.');const changed=selected.map(s=>{const copy={...s};if(mode==='move'){const d=new Date(s.date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+offset);copy.date=d.toISOString().slice(0,10)}else copy.person=target;return copy});const selectedIds=new Set(selected.map(s=>s.id));const other=db.shifts.filter(s=>!selectedIds.has(s.id));for(const s of changed){if(other.some(q=>q.point===s.point&&q.person===s.person&&q.date===s.date)||changed.filter(q=>q.point===s.point&&q.person===s.person&&q.date===s.date).length>1)return sheetError('На одной из дат уже есть такая смена.');if(person(s.person)?.role!=='manager'&&other.some(q=>q.person===s.person&&q.date===s.date&&q.point!==s.point))return sheetError('Пересечение с другим ПВЗ.')}if(commit(()=>{for(let i=0;i<selected.length;i++)Object.assign(selected[i],changed[i])})){bulkSelection=false;selectedDates.clear();closeSheet();render()}}
function calendarCopySheet(){const p=activePoint();if(!p)return;sheetKind='copy';document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>Копировать смены</h3><button onclick="closeSheet()">Закрыть</button></div><form onsubmit="copyCalendarRule(event)">${selectField('Способ копирования','method',[['dates','По числам прошлого месяца'],['weekday','По дням недели прошлого месяца'],['week','Первая неделя → остальные недели']])}<button class="primary wide">Предпросмотр и копирование</button></form><div id="sheet-error" class="sheet-error"></div></section>`;setupSheetKeyboard()}
function copyCalendarRule(e){e.preventDefault();const method=new FormData(e.target).get('method'),p=activePoint(),previous=new Date(year,month-1,1),oldPrefix=`${previous.getFullYear()}-${String(previous.getMonth()+1).padStart(2,'0')}-`,prefix=monthPrefix()+'-',max=new Date(year,month+1,0).getDate(),src=db.shifts.filter(s=>s.point===p.id&&s.date.startsWith(method==='week'?prefix:oldPrefix)&&!s.actual);let changes=[];for(const s of src){const old=new Date(s.date+'T12:00:00Z');if(method==='week'&&old.getUTCDate()>7)continue;const dates=method==='week'?Array.from({length:5},(_,i)=>old.getUTCDate()+7*i):[method==='dates'?old.getUTCDate():1+((old.getUTCDay()-new Date(Date.UTC(year,month,1)).getUTCDay()+7)%7)+7*Math.floor((old.getUTCDate()-1)/7)];for(const d of dates){if(d>max||d<1)continue;const date=prefix+String(d).padStart(2,'0');if(!db.shifts.some(x=>x.point===p.id&&x.person===s.person&&x.date===date)&&!changes.some(x=>x.person===s.person&&x.date===date))changes.push({...s,id:id(),date,actual:false})}}if(!changes.length)return sheetError('Новых смен по этому правилу нет.');if(!ensureNoConflicts(changes))return sheetError('Есть пересечения с другими ПВЗ.');if(!confirm(`Добавить ${changes.length} плановых смен?`))return;if(commit(()=>db.shifts.push(...changes))){closeSheet();render()}}

function undoLast(){if(!undo.length)return;const before=undo.pop(),current=JSON.stringify(db);try{writeLocal(before);redo.push(current);db=JSON.parse(before);render()}catch(e){undo.push(before);alert('Не удалось отменить: '+e.message)}}
function redoLast(){if(!redo.length)return;const next=redo.pop(),current=JSON.stringify(db);try{writeLocal(next);undo.push(current);db=JSON.parse(next);render()}catch(e){redo.push(next);alert('Не удалось вернуть: '+e.message)}}
function addIncident(){openSheet('incident')}
function resolveIncident(i){editIncidentStatus(i)}
function addPayment(){openSheet('payment')}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backup(){download('PVZ_CONTROL_backup_'+new Date().toLocaleDateString('sv-SE')+'.json',JSON.stringify({app:'PVZ_CONTROL',version:1,exported:new Date().toISOString(),data:db},null,2),'application/json')}
async function restore(file){if(!file)return;try{if(file.size>15*1024*1024)throw Error('Архив слишком большой');const obj=JSON.parse(await file.text());if(!obj||typeof obj!=='object')throw Error('Неверный архив');if(obj.app!=='PVZ_CONTROL'||obj.version!==1)throw Error('Неподдерживаемый формат или версия');for(const key of ['reviews','repayments','installments'])if(obj.data[key]===undefined)obj.data[key]=[];validate(obj.data);const before=JSON.stringify(db);if(!confirm(`Архив проверен: ${obj.data.points.length} ПВЗ, ${obj.data.people.length} сотрудников, ${obj.data.shifts.length} смен. Заменить текущие данные?`))return;download('PVZ_CONTROL_before_restore_'+Date.now()+'.json',JSON.stringify({app:'PVZ_CONTROL',version:1,data:db}),'application/json');try{if(typeof checkpoint==='function')checkpoint('before-json-restore');writeLocal(JSON.stringify(obj.data),{recover:true})}catch(e){throw Error('Недостаточно места для восстановления: '+e.message)}db=obj.data;undo.push(before);redo=[];pointId='';render();alert('Архив восстановлен. Контрольная копия прежней базы скачана.')}catch(e){alert('Восстановление отменено: '+e.message)}}
function exportPayrollCsv(){const p=activePoint();if(!p)return;const prefix=monthPrefix();const ids=new Set([...db.shifts.filter(s=>s.point===p.id&&s.date.startsWith(prefix)).map(s=>s.person),...db.payments.filter(x=>x.point===p.id&&x.date.startsWith(prefix)).map(x=>x.person)]);const rows=[['ПВЗ','Месяц','Сотрудник','Фактических смен','Часов','Начислено ₽','Выплачено ₽','Авансы ₽','Разница за месяц ₽']];for(const pid of ids){const w=person(pid);if(!w)continue;const shifts=db.shifts.filter(s=>s.point===p.id&&s.person===pid&&s.actual&&s.date.startsWith(prefix));const hours=roundMoney(shifts.reduce((a,s)=>a+(s.hours??12),0));const earned=roundMoney(shifts.reduce((a,s)=>a+(shiftEarned(s)),0));const payments=db.payments.filter(x=>x.point===p.id&&x.person===pid&&x.date.startsWith(prefix));const paid=roundMoney(payments.reduce((a,x)=>a+x.amount,0)),advances=roundMoney(payments.filter(x=>x.kind==='advance').reduce((a,x)=>a+x.amount,0));rows.push([p.name,prefix,w.name,shifts.length,hours,earned,paid,advances,roundMoney(earned-paid)])}const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n');download('PVZ_CONTROL_payroll_'+prefix+'.csv',csv,'text/csv;charset=utf-8')}
function exportCsv(){const p=activePoint();if(!p)return;const rows=[['Дата','ПВЗ','Сотрудник','Роль','Фактическая']];for(const s of db.shifts.filter(x=>x.point===p.id&&x.date.startsWith(`${year}-${String(month+1).padStart(2,'0')}`)))rows.push([s.date,p.name,person(s.person)?.name||'',person(s.person)?.role||'',s.actual?'Да':'Нет']);const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n');download('PVZ_CONTROL_shifts.csv',csv,'text/csv;charset=utf-8')}

function calendarRows(){const p=activePoint();if(!p)return [];const rows=[['Дата','ПВЗ','Сотрудник','Роль','План/факт','Часов','Начислено, ₽']];for(const s of db.shifts.filter(x=>x.point===p.id&&x.date.startsWith(monthPrefix())).sort((a,b)=>a.date.localeCompare(b.date)))rows.push([s.date,p.name,person(s.person)?.name||'',person(s.person)?.role==='manager'?'Управляющий':'Сотрудник',s.actual?'Отработана':'План',s.actual?s.hours??12:'',s.actual?shiftEarned(s):'']);return rows}
function xmlEscape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]))}
function excelColumn(n){let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s}
function crc32(data){let c=-1;for(const b of data){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xEDB88320:0)}return(c^-1)>>>0}
function zipStore(files){const enc=new TextEncoder(),parts=[],central=[];let offset=0;const u16=(a,n)=>{a.push(n&255,(n>>>8)&255)},u32=(a,n)=>{u16(a,n&65535);u16(a,n>>>16)};for(const [name,body] of files){const n=enc.encode(name),b=enc.encode(body),crc=crc32(b),h=[];u32(h,0x04034b50);u16(h,20);u16(h,0);u16(h,0);u16(h,0);u16(h,0);u32(h,crc);u32(h,b.length);u32(h,b.length);u16(h,n.length);u16(h,0);parts.push(new Uint8Array(h),n,b);const c=[];u32(c,0x02014b50);u16(c,20);u16(c,20);u16(c,0);u16(c,0);u16(c,0);u16(c,0);u32(c,crc);u32(c,b.length);u32(c,b.length);u16(c,n.length);u16(c,0);u16(c,0);u16(c,0);u16(c,0);u32(c,0);u32(c,offset);central.push(new Uint8Array(c),n);offset+=h.length+n.length+b.length}const start=offset;for(const x of central){parts.push(x);offset+=x.length}const e=[];u32(e,0x06054b50);u16(e,0);u16(e,0);u16(e,files.length);u16(e,files.length);u32(e,offset-start);u32(e,start);u16(e,0);parts.push(new Uint8Array(e));return new Blob(parts,{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function exportExcel(){const rows=calendarRows();if(!rows.length)return;const sheet=rows.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>{const ref=excelColumn(j)+(i+1);return typeof v==='number'?`<c r="${ref}"><v>${v}</v></c>`:`<c r="${ref}" t="inlineStr"><is><t>${xmlEscape(v)}</t></is></c>`}).join('')}</row>`).join('');const files=[['[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'],['_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],['xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Смены" sheetId="1" r:id="rId1"/></sheets></workbook>'],['xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'],['xl/worksheets/sheet1.xml',`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${sheet}</sheetData></worksheet>`]];const blob=zipStore(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PVZ_CONTROL_calendar_'+monthPrefix()+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportPdf(){const p=activePoint();if(!p)return;const rows=calendarRows();const win=window.open('','_blank');if(!win){alert('Разрешите открытие окна для PDF, затем выберите «Сохранить как PDF» в меню печати.');return}win.document.write(`<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>PVZ CONTROL — ${xmlEscape(p.name)}</title><style>body{font:12px Arial;padding:24px;color:#222}h1{font-size:20px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #bbb;padding:7px;text-align:left}th{background:#eee}@page{size:A4 landscape;margin:12mm}</style></head><body><h1>${xmlEscape(p.name)} · ${monthPrefix()}</h1><p>Календарь смен · PVZ CONTROL</p><table><thead><tr>${rows[0].map(x=>`<th>${xmlEscape(x)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map(r=>`<tr>${r.map(x=>`<td>${xmlEscape(x)}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);win.document.close()}

const SVG={'chevron-right':'<path d="m9 18 6-6-6-6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>','calendar-days':'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M8 14h2M14 14h2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5"/>',store:'<path d="M3 10 5 3h14l2 7v11H3V10ZM3 10h18M9 21v-8h6v8"/>','layout-grid':'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',wallet:'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M3 10h18M6 6V4h12"/>',alert:'<path d="M12 3 2 21h20L12 3ZM12 9v5M12 18h.01"/>',note:'<path d="M5 3h14v18H5zM8 8h8M8 12h8M8 16h5"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>'};
function ico(name){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${SVG[name]||SVG.plus}</svg>`}
let profileId='';let sheetKind='';
let sheetCleanup=()=>{};
function closeSheet(){sheetCleanup();closeDatePicker();document.getElementById('sheet-root').innerHTML='';sheetKind='';document.body.classList.remove('sheet-open')}
function setupSheetKeyboard(){
 sheetCleanup();document.body.classList.add('sheet-open');
 const sheet=document.querySelector('.sheet');if(!sheet)return;
 const savedY=window.scrollY||0,body=document.body,previous={position:body.style.position,top:body.style.top,width:body.style.width};
 body.style.position='fixed';body.style.top=-savedY+'px';body.style.width='100%';
 const baseline=window.innerHeight,compact=(window.innerWidth||1024)<=600;
 const adjust=()=>{const v=window.visualViewport;if(!v)return;
  const height=Math.max(120,Math.min(v.height,window.innerHeight)-16);
  sheet.style.maxHeight=height+'px';
  if(compact||v.height<baseline*.8){sheet.style.top=Math.max(8,v.offsetTop+8)+'px';sheet.style.bottom='auto';if(compact)sheet.style.height=height+'px'}
  else{sheet.style.top='auto';sheet.style.bottom=Math.max(0,window.innerHeight-v.height-v.offsetTop)+'px'}
 };
 const reveal=()=>{const field=document.activeElement;if(!field||!sheet.contains(field))return;
  const box=field.getBoundingClientRect(),bounds=sheet.getBoundingClientRect();
  if(box.bottom>bounds.bottom-24)sheet.scrollTop+=box.bottom-bounds.bottom+24;
  else if(box.top<bounds.top+24)sheet.scrollTop-=bounds.top+24-box.top;
 };
 let focusTimer;
 const onFocus=()=>{clearTimeout(focusTimer);focusTimer=setTimeout(()=>{adjust();reveal()},220)};
 const onResize=()=>{adjust();reveal()};
 sheetCleanup=()=>{clearTimeout(focusTimer);window.visualViewport?.removeEventListener('resize',onResize);window.visualViewport?.removeEventListener('scroll',adjust);sheet.removeEventListener('focusin',onFocus);Object.assign(body.style,previous);window.scrollTo?.(0,savedY)};
 adjust();window.visualViewport?.addEventListener('resize',onResize);window.visualViewport?.addEventListener('scroll',adjust);sheet.addEventListener('focusin',onFocus);
}

function field(label,name,type='text',extra=''){
 if((name==='date'||name==='start'||name==='first')&&(type==='text'||type==='date')){
  const value=(extra.match(/value="(\d{4}-\d{2}-\d{2})"/)||[])[1]||'';
  const required=/\brequired\b/.test(extra)?'required':'';
  return `<div class="form-field date-field"><label>${esc(label.replace(/\s*\(ГГГГ-ММ-ДД\)/g,''))}</label><input type="hidden" name="${esc(name)}" value="${esc(value)}" ${required}><button type="button" class="date-pick-trigger" onclick="openDatePicker(this)" aria-label="Выбрать дату: ${esc(label)}">${ico('calendar-days')}<span class="date-pick-label">${value?formatPickedDate(value):'Выбрать дату'}</span>${ico('chevron-right')}</button></div>`;
 }
 return `<label class="form-field"><span>${label}</span><input name="${name}" type="${type}" ${extra}></label>`;
}
function formatPickedDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return 'Выбрать дату';const [y,m,d]=value.split('-').map(Number);return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date(y,m-1,d))}
let pickerTarget=null,pickerMonth=0,pickerYear=0,pickerFocus=null;
function openDatePicker(trigger){
 pickerTarget=trigger.closest('.date-field');if(!pickerTarget)return;
 const raw=pickerTarget.querySelector('input[name]')?.value||'';
 const today=new Date(),chosen=dateValid(raw)?new Date(Number(raw.slice(0,4)),Number(raw.slice(5,7))-1,Number(raw.slice(8,10))):today;
 pickerMonth=chosen.getMonth();pickerYear=chosen.getFullYear();pickerFocus=document.activeElement;
 let overlay=document.getElementById('date-picker-overlay');if(!overlay){overlay=document.createElement('div');overlay.id='date-picker-overlay';document.body.appendChild(overlay)}
 overlay.innerHTML='<div class="date-picker-backdrop" onclick="closeDatePicker()"></div><section class="date-picker-panel" role="dialog" aria-modal="true" aria-label="Выберите дату"><div class="date-picker-head"><strong>Выберите дату</strong><button type="button" onclick="closeDatePicker()" aria-label="Закрыть">×</button></div><div id="date-picker-grid"></div><div class="date-picker-footer"><button type="button" onclick="choosePickerToday()">Сегодня</button><button type="button" onclick="closeDatePicker()">Отмена</button></div></section>';
 document.body.classList.add('date-picker-open');renderDatePicker();overlay.querySelector('.date-picker-head button').focus();
}
function renderDatePicker(){const root=document.getElementById('date-picker-grid');if(!root)return;const start=(new Date(pickerYear,pickerMonth,1).getDay()+6)%7,days=new Date(pickerYear,pickerMonth+1,0).getDate(),today=new Date(),todayStr=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-'),selected=pickerTarget?.querySelector('input[name]')?.value;
 const monthLabel=new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(pickerYear,pickerMonth,1));
 root.innerHTML=`<div class="date-picker-month"><button type="button" onclick="movePickerMonth(-1)" aria-label="Предыдущий месяц">‹</button><strong>${monthLabel}</strong><button type="button" onclick="movePickerMonth(1)" aria-label="Следующий месяц">›</button></div><div class="date-picker-days">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span class="date-picker-weekday">${x}</span>`).join('')}${Array.from({length:start},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const d=i+1,v=`${pickerYear}-${String(pickerMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;return `<button type="button" class="date-picker-day${v===selected?' selected':''}${v===todayStr?' today':''}" aria-label="${formatPickedDate(v)}" aria-pressed="${v===selected}" onclick="choosePickerDate('${v}')">${d}</button>`}).join('')}</div>`;
}
function movePickerMonth(offset){const d=new Date(pickerYear,pickerMonth+offset,1);pickerYear=d.getFullYear();pickerMonth=d.getMonth();renderDatePicker()}
function choosePickerDate(value){if(!pickerTarget||!dateValid(value))return;const input=pickerTarget.querySelector('input[name]');input.value=value;pickerTarget.querySelector('.date-pick-label').textContent=formatPickedDate(value);input.dispatchEvent(new Event('change',{bubbles:true}));closeDatePicker()}
function choosePickerToday(){const n=new Date();choosePickerDate(`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`)}
function closeDatePicker(){document.getElementById('date-picker-overlay')?.remove();document.body.classList.remove('date-picker-open');pickerTarget=null;pickerFocus?.focus?.();pickerFocus=null}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('date-picker-overlay')){e.preventDefault();closeDatePicker()}});

function selectField(label,name,opts){return `<label class="form-field"><span>${label}</span><select name="${name}">${opts.map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('')}</select></label>`}
function staffOptions(){const p=activePoint();return db.people.filter(x=>!x.archived&&(!x.points?.length||x.points.includes(p?.id))).map(x=>[x.id,x.name])}
function openSheet(kind){sheetKind=kind;const p=activePoint();const date=selectedDay||new Date().toLocaleDateString('sv-SE');let title='',content='';
if(kind==='menu'){title='Что добавить?';content=`<div class="action-grid">${[['point','store','ПВЗ','Новый пункт'],['person','users','Сотрудника','В команду'],['day','calendar','Смену','В календарь'],['payment','wallet','Выплату','Зарплата или аванс'],['incident','alert','Проблему','Штраф или претензия'],['note','note','Заметку','К рабочему дню']].map(([k,i,n,d])=>`<button type="button" class="action-tile" onclick="${k==='day'&&!selectedDay?"selectedDay=new Date().toLocaleDateString('sv-SE');":''}openSheet('${k}')">${ico(i)}<strong>${n}</strong><small>${d}</small></button>`).join('')}</div>`}
if(kind==='point'){title='Новый ПВЗ';content=`<form id="quick-form" onsubmit="submitSheet(event)">${field('Название или адрес','name','text','required maxlength="120" placeholder="Например, Ленина, 12"')}${selectField('Маркетплейс','market',[['wb','Wildberries'],['ozon','Ozon'],['ym','Яндекс Маркет']])}<button class="primary wide" type="submit">Создать ПВЗ</button></form>`}
if(kind==='person'){title='Новый сотрудник';content=`<form id="quick-form" onsubmit="submitSheet(event)">${field('Имя сотрудника','name','text','required maxlength="120" placeholder="Как обращаться к сотруднику"')}${selectField('ПВЗ','point',db.points.map(x=>[x.id,x.name]))}${selectField('Роль','role',[['employee','Сотрудник'],['manager','Управляющий']])}${selectField('График','pattern',[['','Пока без графика'],...patternDays.map(x=>[x,x])])}<details class="advanced-fields"><summary>Дополнительные настройки</summary>${field('Ставка за смену, ₽','rate','number','min="0" step="0.01" value="0"')}${field('Почасовая ставка, ₽','hourlyRate','number','min="0" step="0.01" value="0"')}${field('Первый рабочий день','start','text',`value="${date}" pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}"`)}<label class="checkline"><input type="checkbox" name="substitute"> Подменный сотрудник</label></details><button class="primary wide" type="submit">Сохранить сотрудника</button></form>`}
if(kind==='day'){title=`Смены · ${date.split('-').reverse().join('.')}`;content=`<div class="shift-list">${p?shiftAt(p.id,date).map(s=>`<div class="shift-line"><span class="person-dot" style="background:${esc(person(s.person)?.color||'#aaa')}"></span><div class="grow"><strong>${esc(person(s.person)?.name||'')}</strong><small>${s.actual?'Отработана':'Запланирована'}</small></div><button onclick="markShift('${s.id}')" aria-label="Отметить смену">${s.actual?'Снять факт':'Отработана'}</button>${s.actual?`<button onclick="editHours('${s.id}')">${s.hours??12} ч</button>`:''}<button onclick="removeShift('${s.id}')" aria-label="Удалить смену">${ico('close')}</button></div>`).join(''):''}</div><form id="quick-form" onsubmit="submitSheet(event)"><input type="hidden" name="date" value="${date}"><p class="selected-date">${date.split('-').reverse().join('.')}</p>${selectField('Сотрудник','person',staffOptions())}<button class="primary wide" type="submit" ${!p||!staffOptions().length?'disabled':''}>Добавить смену</button></form>${!staffOptions().length?'<p class="muted">Сначала добавьте сотрудника.</p>':''}`}
if(kind==='payment'){title='Новая выплата';content=`<form id="quick-form" onsubmit="submitSheet(event)">${selectField('Сотрудник','person',staffOptions())}${selectField('Вид выплаты','kind',[['salary','Зарплата'],['advance','Аванс'],['other','Другая выплата']])}${field('Сумма, ₽','amount','number','required min="0.01" step="0.01" placeholder="0"')}${field('Дата (ГГГГ-ММ-ДД)','date','text',`required inputmode="numeric" pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}" value="${date}"`)}<button class="primary wide" type="submit" ${!p||!staffOptions().length?'disabled':''}>Сохранить выплату</button></form>`}
if(kind==='incident'){title='Новая проблема';content=`<form id="quick-form" onsubmit="submitSheet(event)">${selectField('Сотрудник','person',staffOptions())}${selectField('Тип','type',(p?.market==='wb'?['штраф','подмена','зависшие','брак','приёмка +','приёмка -','потеряшка']:['штраф','претензия','приёмка +','приёмка -','потеряшка']).map(x=>[x,x]))}${field('Сумма, ₽','amount','number','required min="0" step="0.01" placeholder="0"')}${field('Дата (ГГГГ-ММ-ДД)','date','text',`required inputmode="numeric" pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}" value="${date}"`)}<details class="advanced-fields"><summary>Данные товара</summary>${field('Штрихкод','barcode')}${field('Комментарий','comment')}${field('Стоимость товара, ₽','price','number','min="0" step="0.01"')}${field('Процент','percent','number','min="0" max="200" step="0.01"')}</details><button class="primary wide" type="submit" ${!p||!staffOptions().length?'disabled':''}>Сохранить проблему</button></form>`}
if(kind==='note'){title='Новая заметка';content=`<form id="quick-form" onsubmit="submitSheet(event)">${field('Дата (ГГГГ-ММ-ДД)','date','text',`required inputmode="numeric" pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}" value="${date}"`)}<label class="form-field"><span>Текст заметки</span><textarea name="text" required maxlength="2000" rows="4"></textarea></label><button class="primary wide" type="submit" ${!p?'disabled':''}>Сохранить заметку</button></form>`}
if(kind==='schedule'){title='Заполнить график';content=`<form id="quick-form" onsubmit="submitSheet(event)">${selectField('График','pattern',patternDays.map(x=>[x,x]))}${field('Первый рабочий день (ГГГГ-ММ-ДД)','start','text',`required pattern="[0-9]{4}-[0-9]{2}-[0-9]{2}" value="${date}"`)}${selectField('На сколько месяцев','months',Array.from({length:12},(_,i)=>[String(i+1),`${i+1}`]))}<button class="primary wide" type="submit">Заполнить календарь</button></form>`}
document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true" aria-label="${title}"><div class="sheet-head"><h3>${title}</h3><button class="sheet-close" onclick="closeSheet()" aria-label="Закрыть">${ico('close')}</button></div>${content}<div id="sheet-error" class="sheet-error" role="alert"></div></section>`;setupSheetKeyboard()}
let schedulePerson='';function scheduleSheet(pid){schedulePerson=pid;openSheet('schedule')}
function sheetError(msg){document.getElementById('sheet-error').textContent=msg}
function submitSheet(e){e.preventDefault();const f=new FormData(e.currentTarget),get=n=>String(f.get(n)||'').trim(),p=activePoint(),kind=sheetKind;let ok=false;
if(kind==='point'){if(!get('name')||get('name').length>120||!['wb','ozon','ym'].includes(get('market')))return sheetError('Укажите название ПВЗ и маркетплейс.');const point={id:id(),name:get('name'),market:get('market')};ok=commit(()=>db.points.push(point));if(ok)pointId=point.id}
if(kind==='person'){if(!db.points.length)return sheetError('Сначала создайте ПВЗ.');const rate=Number(get('rate')||0),hourlyRate=Number(get('hourlyRate')||0);if(!amountValid(rate,true)||!amountValid(hourlyRate,true))return sheetError('Проверьте ставку.');const who={id:id(),name:get('name'),role:get('role'),substitute:get('role')==='employee'&&f.has('substitute'),color:colors[db.people.length%colors.length],rate,hourlyRate,archived:false,points:get('role')==='manager'?[get('point')]:[]};ok=commit(()=>db.people.push(who));if(ok){pointId=get('point');const pattern=get('pattern');if(pattern){const [work,rest]=pattern.split('/').map(Number),start=get('start')||new Date().toLocaleDateString('sv-SE'),changes=[];for(let d=1;d<=new Date(year,month+1,0).getDate();d++){const date=dateStr(d),diff=Math.round((Date.parse(date+'T12:00:00Z')-Date.parse(start+'T12:00:00Z'))/86400000);if(diff>=0&&(pattern==='5/2 (будни)'?new Date(date+'T12:00:00Z').getUTCDay()%6!==0:diff%(work+rest)<work))changes.push({id:id(),point:pointId,person:who.id,date,actual:false})}if(changes.length&&ensureNoConflicts(changes))commit(()=>db.shifts.push(...changes))}}}
if(kind==='day'){const date=get('date'),pid=get('person');if(!dateValid(date)||!pid)return sheetError('Укажите дату и сотрудника.');if(db.shifts.some(s=>s.point===p.id&&s.person===pid&&s.date===date))return sheetError('Этот сотрудник уже назначен на эту дату.');if(person(pid)?.role!=='manager'&&conflicting(pid,date,p.id).length)return sheetError('Сотрудник уже работает в другом ПВЗ в этот день.');ok=commit(()=>db.shifts.push({id:id(),point:p.id,person:pid,date,actual:false}));selectedDay=date}
if(kind==='payment'){const amount=Number(get('amount'));if(!amountValid(amount)||!dateValid(get('date')))return sheetError('Проверьте сумму и дату.');ok=commit(()=>db.payments.push({id:id(),point:p.id,person:get('person'),amount,kind:get('kind')||'salary',date:get('date')}))}
if(kind==='incident'){const amount=Number(get('amount')),price=Number(get('price')||amount),percent=Number(get('percent')||100);if(!amountValid(amount,true)||!amountValid(price,true)||percent<0||percent>200||!dateValid(get('date')))return sheetError('Проверьте сумму, процент и дату.');ok=commit(()=>db.incidents.push({id:id(),point:p.id,person:get('person'),type:get('type'),barcode:get('barcode'),comment:get('comment'),price,percent,amount,status:'новое',date:get('date')}))}
if(kind==='note'){if(!dateValid(get('date'))||!get('text'))return sheetError('Укажите дату и текст.');ok=commit(()=>db.notes.push({id:id(),point:p.id,date:get('date'),text:get('text')}))}
if(kind==='schedule'){const who=person(schedulePerson),[work,rest]=get('pattern').split('/').map(Number),start=get('start'),months=Number(get('months'));if(!who||!dateValid(start))return sheetError('Проверьте дату.');const changes=[];for(let m=0;m<months;m++){const base=new Date(year,month+m,1);for(let d=1;d<=new Date(base.getFullYear(),base.getMonth()+1,0).getDate();d++){const date=`${base.getFullYear()}-${String(base.getMonth()+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,diff=Math.round((Date.parse(date+'T12:00:00Z')-Date.parse(start+'T12:00:00Z'))/86400000);if(diff>=0&&(get('pattern')==='5/2 (будни)'?new Date(date+'T12:00:00Z').getUTCDay()%6!==0:diff%(work+rest)<work)&&!db.shifts.some(s=>s.point===p.id&&s.person===who.id&&s.date===date))changes.push({id:id(),point:p.id,person:who.id,date,actual:false})}}if(!ensureNoConflicts(changes))return sheetError('Обнаружены пересечения смен.');ok=changes.length?commit(()=>db.shifts.push(...changes)):true}
if(ok){closeSheet();if(kind==='day')openSheet('day');else if(kind==='person')go('people');else if(kind==='point')go('calendar');else render()}}
function editHours(sid){const s=db.shifts.find(x=>x.id===sid);if(!s)return;sheetKind='hours';document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>Отработанные часы</h3><button onclick="closeSheet()">Закрыть</button></div><form onsubmit="event.preventDefault();const n=Number(new FormData(this).get('hours'));if(!Number.isFinite(n)||n<0||n>24)return sheetError('От 0 до 24 часов');if(commit(()=>{db.shifts.find(x=>x.id==='${sid}').hours=n})){closeSheet();openSheet('day')}"><label class="form-field">Часов за смену<input name="hours" type="number" min="0" max="24" step="0.25" value="${s.hours??12}" required></label><button class="primary wide">Сохранить</button></form><div id="sheet-error" class="sheet-error"></div></section>`;setupSheetKeyboard()}
function editIncidentStatus(sid){const q=db.incidents.find(x=>x.id===sid);if(!q)return;sheetKind='incident-status';document.getElementById('sheet-root').innerHTML=`<div class="sheet-backdrop" onclick="closeSheet()"></div><section class="sheet" role="dialog" aria-modal="true"><div class="sheet-head"><h3>Статус происшествия</h3><button onclick="closeSheet()">Закрыть</button></div><form onsubmit="event.preventDefault();const value=new FormData(this).get('status');if(commit(()=>{db.incidents.find(x=>x.id==='${sid}').status=value}))closeSheet()">${selectField('Статус','status',['новое','рассматривается','оспаривается','подтверждено','отменено'].map(x=>[x,x]))}<button class="primary wide">Сохранить</button></form></section>`;setupSheetKeyboard();document.querySelector('#sheet-root select').value=q.status}
function removeShift(sid){const s=db.shifts.find(x=>x.id===sid);if(!s)return;if(commit(()=>{db.shifts=db.shifts.filter(x=>x.id!==sid)}))openSheet('day')}
function markShift(sid){const s=db.shifts.find(x=>x.id===sid);if(!s)return;if(commit(()=>{s.actual=!s.actual;if(s.actual){s.hours=s.hours??(Number(db.settings?.defaultHours)||12);freezeShiftRate(s)}}))openSheet('day')}

try{const prefs=JSON.parse(localStorage.getItem(KEY+'-view')||'null');if(prefs){pointId=typeof prefs.pointId==='string'?prefs.pointId:'';networkMarket=['all','wb','ozon','ym'].includes(prefs.networkMarket)?prefs.networkMarket:'all';settingsQuery=typeof prefs.settingsQuery==='string'?prefs.settingsQuery:''}}catch{}
try{validate(db)}catch(e){storageFault=true;db=empty();setTimeout(()=>alert('База не прошла проверку: '+e.message+'. Исходные данные сохранены; изменения заблокированы.'),0)}
render();
if(storageFault)setTimeout(()=>alert('Локальное хранилище недоступно или повреждено. Не удаляйте данные браузера. Экспортируйте исходную копию в разделе синхронизации.'),0);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateCurrentDate()});
window.addEventListener('focus',updateCurrentDate);
setInterval(updateCurrentDate,60000);
